import { useState, type FormEvent } from 'react';
import { JxStepper, JxInputField, JxSelect, JxButton } from '@jinx-ui/react';

type RegistrationData = {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  postalCode: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const COUNTRY_OPTIONS = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [country, setCountry] = useState('');
  const [city, setCity] = useState('');
  const [street, setStreet] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const lastStepIndex = STEPS.length - 1;
  const isLastStep = step === lastStepIndex;

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, lastStepIndex));

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isLastStep) {
      goNext();
      return;
    }
    onSubmit({ fullName, email, phone, country, city, street, postalCode });
  };

  const countryLabel = COUNTRY_OPTIONS.find((option) => option.value === country)?.label;

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 24, color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Имя и фамилия"
            name="fullName"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            name="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            name="phone"
            required
            helperText="Например, +7 900 000-00-00"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxSelect
            label="Страна"
            options={COUNTRY_OPTIONS}
            value={country}
            onValueChange={setCountry}
          />
          <JxInputField
            label="Город"
            name="city"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            name="street"
            required
            value={street}
            onChange={(event) => setStreet(event.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            name="postalCode"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <dl style={{ display: 'flex', flexDirection: 'column', gap: 12, margin: 0 }}>
          <div>
            <dt className="jx-label">Имя и фамилия</dt>
            <dd style={{ margin: 0 }}>{fullName || '—'}</dd>
          </div>
          <div>
            <dt className="jx-label">Электронная почта</dt>
            <dd style={{ margin: 0 }}>{email || '—'}</dd>
          </div>
          <div>
            <dt className="jx-label">Телефон</dt>
            <dd style={{ margin: 0 }}>{phone || '—'}</dd>
          </div>
          <div>
            <dt className="jx-label">Адрес</dt>
            <dd style={{ margin: 0 }}>
              {[countryLabel, city, street, postalCode].filter(Boolean).join(', ') || '—'}
            </dd>
          </div>
        </dl>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
        <JxButton type="button" variant="ghost" onClick={goBack} disabled={step === 0}>
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

